// probe: compile-only
io :: import "std/io"

Choice :: enum { First, Second }
main :: fn() {
    x := 5
    k := Choice.Second
    match k {
        case Choice.First: {
            x = 0
            fall
        }
        case Choice.Second: {
            io.println("{}", 10 / x)
        }
    }
}

